/*
 * src/lib/reports/report-csv.ts
 *
 * WHAT: Turns the report figures into CSV ROWS (Step 37, FR-06 SR-6.9):
 *         closeoutCsvRows(...)    -> the Daily Closeout report (one day);
 *         dailyTotalsCsvRows(...) -> the daily totals of a date range;
 *         itemVolumeCsvRows(...)  -> the item volume report.
 *       Every file starts with the same HEADER LINES (decision): The Spot,
 *       report name, day / range, generated at, generated by, FINAL / DRAFT,
 *       then a blank line, then the table(s).
 *
 * LAYER: Application layer. The export routes (src/app/manager/export/...)
 *        load the figures (the database works them out and checks the
 *        role), then call these to lay them out. NOTHING is calculated
 *        here: the CSV shows exactly the database's figures, like the page.
 *
 * Amounts are plain numbers (money(...) -> 1200.00) with "(J$)" in the
 * column name, so a spreadsheet can add them up.
 */

import { PAYMENT_METHOD_LABELS, STATUS_LABELS } from "@/lib/order-status";
import { money, type CsvValue } from "@/lib/reports/csv";
import type { CloseoutDetails } from "@/lib/reports/get-closeout";
import { ITEM_SORTS, type ItemFilters, type ItemVolumeLine } from "@/lib/reports/get-item-volume";
import type { SalesRange, SalesSummary } from "@/lib/reports/get-sales-summary";
import {
  CLOSEOUT_EVENT_TEXT,
  CLOSEOUT_STATUS_TEXT,
  formatReportTime,
  type ReportInfo,
  type ReportState,
} from "@/lib/reports/report-info";

type Rows = CsvValue[][];

/*
 * headerRows(info, state, periodName) -> the lines at the top of every file,
 * then one blank line. periodName: "Business day" (one day) or "Period".
 */
function headerRows(info: ReportInfo, state: ReportState, periodName: string): Rows {
  return [
    [info.business],
    ["Report", info.title],
    [periodName, info.period],
    ["Generated", `${info.generatedAt} (Jamaica time)`],
    ["Generated by", info.generatedBy],
    ["Report status", state.label],
    [],
  ];
}

/* The day's figures (shared by the closeout file). Same order as the page. */
function summaryRows(summary: SalesSummary): Rows {
  return [
    ["Sales (paid orders only)"],
    ["Orders (paid)", summary.orders],
    ["Gross sales (J$)", money(summary.grossSales)],
    ["of which delivery fees (J$)", money(summary.deliveryFees)],
    ["Refunds (J$)", money(summary.refunds)], // refunds issued that day (Step 38b)
    ["Net sales (J$)", money(summary.netSales)],
    // AC-6.3: the payment-type totals must equal net sales.
    ["Payment totals match net sales", summary.totalsMatch ? "Yes" : "NO - please check"],
    [],
    ["By payment type"],
    ["Type", "Transactions", "Amount (J$)", "Refunds (J$)", "Net (J$)", "% of net"],
    ...summary.byMethod.map((line) => [
      PAYMENT_METHOD_LABELS[line.method],
      line.transactions,
      money(line.amount),
      money(line.refunds),
      money(line.net),
      line.percent,
    ]),
    [],
    ["Not counted in sales"],
    ["Type", "Orders", "Value (J$)"],
    ["Cancelled", summary.cancelledCount, money(summary.cancelledValue)],
    ["Abandoned", summary.abandonedCount, money(summary.abandonedValue)],
    ["Not paid yet", summary.notCountedCount, money(summary.notCountedValue)],
  ];
}

/*
 * closeoutCsvRows(info, state, summary, details) -> the Daily Closeout file:
 * header, the day's figures, the cash closeout, and the history.
 */
export function closeoutCsvRows(
  info: ReportInfo,
  state: ReportState,
  summary: SalesSummary,
  details: CloseoutDetails
): Rows {
  const c = details.closeout;
  const time = (ms: number | null) => (ms ? formatReportTime(ms) : null);

  const cashRows: Rows = c
    ? [
        ["Closeout status", CLOSEOUT_STATUS_TEXT[c.status]],
        // The figures SAVED with the count (the ones the Manager approves).
        ["Expected cash (J$)", money(c.expectedCash)],
        ["Counted cash (J$)", money(c.countedCash)],
        ["Difference (J$) (counted - expected)", money(c.cashDifference)],
        ["Explanation", c.differenceNote || null],
        ["Counted by", c.submittedBy],
        ["Counted at", time(c.submittedAt)],
        ["Approved by", c.approvedBy],
        ["Approved at", time(c.approvedAt)],
        ["Closed with open orders (reason)", c.overrideReason],
      ]
    : [
        ["Closeout status", CLOSEOUT_STATUS_TEXT.NONE],
        ["Expected cash now (J$)", money(details.expectedCash)],
        ["Counted cash (J$)", null],
      ];

  return [
    ...headerRows(info, state, "Business day"),
    ...summaryRows(summary),
    [],
    ["Cash closeout"],
    ...cashRows,
    [
      "Open orders",
      details.openOrders.length === 0
        ? "None"
        : details.openOrders.map((o) => `#${o.id} (${STATUS_LABELS[o.status]})`).join("; "),
    ],
    [],
    ["History"],
    ["Date and time", "Action", "By", "Reason"],
    ...details.events.map((e) => [formatReportTime(e.createdAt), CLOSEOUT_EVENT_TEXT[e.action], e.actor, e.reason]),
  ];
}

/*
 * dailyTotalsCsvRows(info, state, range, closedDays) -> one line per day
 * (dates as 2026-11-24 so spreadsheets sort them), then the Total line
 * (the DATABASE's total, as on the page).
 */
export function dailyTotalsCsvRows(info: ReportInfo, state: ReportState, range: SalesRange, closedDays: string[]): Rows {
  const total = range.total;
  const net = (method: "CASH" | "LYNK") => total.byMethod.find((line) => line.method === method)?.net ?? 0;

  return [
    ...headerRows(info, state, "Period"),
    ["Date", "Orders", "Gross (J$)", "Refunds (J$)", "Net (J$)", "Cash (J$)", "Lynk (J$)", "Closed"],
    ...range.days.map((day) => [
      day.day,
      day.orders,
      money(day.grossSales),
      money(day.refunds),
      money(day.netSales),
      money(day.cash),
      money(day.lynk),
      closedDays.includes(day.day) ? "Yes" : "No",
    ]),
    [
      `Total (${range.days.length} days)`,
      total.orders,
      money(total.grossSales),
      money(total.refunds),
      money(total.netSales),
      money(net("CASH")),
      money(net("LYNK")),
      `${closedDays.length} of ${range.days.length}`,
    ],
  ];
}

/* The filters in words, for the file and the printed page. */
export function itemFilterText(filters: ItemFilters): { category: string; type: string; sort: string } {
  return {
    category: filters.category ?? "All categories",
    type: filters.fulfilment === "PICKUP" ? "Pickup only" : filters.fulfilment === "DELIVERY" ? "Delivery only" : "Pickup and delivery",
    // The same words as the "Sort by" list on the page.
    sort: ITEM_SORTS.find((s) => s.value === filters.sort)?.label ?? filters.sort,
  };
}

/*
 * itemVolumeCsvRows(info, state, lines, filters) -> the chosen filters, then
 * one line per item AND size (Size in its own column), then the Total.
 * The total is added up in CENTS (whole numbers) so J$ never get rounding errors.
 */
export function itemVolumeCsvRows(info: ReportInfo, state: ReportState, lines: ItemVolumeLine[], filters: ItemFilters): Rows {
  const words = itemFilterText(filters);
  const totalQuantity = lines.reduce((sum, line) => sum + line.quantity, 0);
  const totalRevenue = lines.reduce((sum, line) => sum + Math.round(line.revenue * 100), 0) / 100;

  return [
    ...headerRows(info, state, "Period"),
    ["Category", words.category],
    ["Order type", words.type],
    ["Sorted by", words.sort],
    [],
    ["Item", "Size", "Category", "Quantity", "Revenue (J$)"],
    ...lines.map((line) => [line.name, line.size, line.category, line.quantity, money(line.revenue)]),
    ["Total", null, null, totalQuantity, money(totalRevenue)],
  ];
}
